// C++20 Concepts for Constrained Templates
template<typename T>
concept Integral = std::is_integral_v<T>;

template<Integral T>
T add_one(T val) { return val + 1; }

// Trailing Return Type Deduction (C++14+)
template<typename T, typename U>
auto multiply(T a, U b) -> decltype(a * b) {
    return a * b;
}

// SFINAE using std::enable_if (Pre-C++20)
template<typename T,
         typename = std::enable_if_t<std::is_arithmetic_v<T>>>
T safe_divide(T num, T den) {
    return num / den;
}

// `if constexpr` (C++17+) for conditional compilation
template<typename T>
void process(const T& val) {
    if constexpr (std::is_pointer_v<T>) {
        std::cout << "Pointer dereferenced: " << *val;
    } else {
        std::cout << "Value: " << val;
    }
}

// Variadic Templates and Fold Expressions (C++17)
template<typename... Args>
auto sum_all(Args... values) {
    return (values + ... + 0); // Binary Left Fold
}

// Universal References and perfect forwarding
template<typename T>
void wrapper(T&& arg) {
    some_func(std::forward<T>(arg));
}
